enum ReadingRules { static let data=try! JSONDecoder().decode(JSONValue.self,from:Data(#"{"formats":[{"id":"profile_description","name":"Informational Profile & Description","description":"A continuous descriptive passage about a person, place, or daily life.","directive":"Write as a clear, authentic short profile or description of a person, place, routine, or everyday setting. Write in natural, continuous prose. ABSOLUTELY NO SCRIPTS, DIALOGUE, OR SPEAKER LABELS ('A:', 'B:')."},{"id":"practical_notice","name":"Public Sign / Notice / Bulletin","description":"An authentic sign, community notice, schedule, or store announcement.","directive":"Write as an authentic public notice, store window sign, transit announcement, or community flyer. Include practical everyday details clearly in informative sentences. ABSOLUTELY NO SCRIPTS, DIALOGUE, OR SPEAKER LABELS ('A:', 'B:')."},{"id":"personal_note","name":"Short Personal Note / Postcard","description":"A note left on a table, a postcard, or a brief message.","directive":"Write as a short personal note, postcard, or brief message left for a friend, roommate, or colleague ('I' / 'we'). Single-author message only — ABSOLUTELY NO SCRIPTS, DIALOGUE, OR SPEAKER LABELS ('A:', 'B:')."},{"id":"everyday_guide","name":"Daily Life Guide / Menu / Helpful Tips","description":"A café menu, schedule, simple recipe step, or practical tip.","directive":"Write as an authentic daily-life informational item: a café menu board, event schedule, simple recipe steps, or a bite-sized practical tip. ABSOLUTELY NO SCRIPTS, DIALOGUE, OR SPEAKER LABELS ('A:', 'B:')."},{"id":"diary_entry","name":"Diary Entry","directive":"A single writer records a specific experience and its personal significance. Connect observations and feelings; avoid a list of reactions or a predictable happy ending."},{"id":"photo_caption","name":"Photo Caption / Album Entry","directive":"Write a self-contained album caption. Describe concrete visible details and why this moment or object matters, so no actual image is needed to understand the text."},{"id":"field_notes","name":"Nature / Observation Notes","directive":"Record closely observed details of an animal, object, weather pattern, or place. Give the reader something specific to notice; do not introduce imaginary speakers."},{"id":"personal_update","name":"Personal Update / Blog Entry","directive":"One author shares a concrete development, plan, or discovery with readers. Give meaningful circumstances and consequences, with a consistent single-author voice."},{"id":"mini_review","name":"Short Review","directive":"Give a personal assessment of a place, object, food, or experience grounded in specific details. Let the details justify the opinion; do not default to generic praise."},{"id":"object_label","name":"Object / Exhibit Label","directive":"Describe one object, its use, and a detail that makes it interesting. Use accurate everyday facts; do not invent historical dates or provenance."},{"id":"comparison","name":"Comparison Piece","directive":"Help a reader understand meaningful differences between two places, objects, routines, or choices using connected prose. Choose details relevant to the lesson rather than a stock pros-and-cons template."},{"id":"how_it_works","name":"How It Works / Mini Explainer","minLevel":"A1","directive":"Explain an everyday process or the reason behind an observation using accurate, accessible facts. Organize it around the subject's logic, without an introduction-body-conclusion formula."},{"id":"news_brief","name":"Local News Brief","minLevel":"A1","directive":"Report a small imagined local development and its practical effect on people. Use informative prose without quotations, interviews, invented claims about real people, or unsupported current events."},{"id":"travel_entry","name":"Travel Journal","minLevel":"A1","directive":"A single writer records a distinctive detail from a visit or journey and what it changed about their understanding or plans. Avoid the stock arrival-activity-happy-ending sequence."},{"id":"historical_snapshot","name":"Historical / Cultural Snapshot","minLevel":"A2","directive":"Describe a well-established historical practice or cultural change relevant to the lesson. Be specific without invented dates, quotations, or sweeping cultural stereotypes."},{"id":"opinion_column","name":"Opinion / Reflective Essay","minLevel":"B1","directive":"Explore a focused claim or question through reasons and concrete observations. Let the argument determine its shape; avoid stock essay transitions and a mandatory moral or summary."}],"angles":[{"id":"daily_context","name":"Daily Context & Setting","guidance":"Focus on the physical environment, time of day, and familiar surroundings."},{"id":"personal_connection","name":"Personal Connection & Role","guidance":"Highlight what the person does, their role, and how the learner/narrator knows them."},{"id":"routine_habits","name":"Routine & Shared Habits","guidance":"Describe regular habits, daily routines, or typical activities."},{"id":"practical_details","name":"Practical Facts & Helpful Info","guidance":"Provide concrete, useful details and observations."},{"id":"unexpected_detail","name":"An Overlooked Detail","guidance":"Explore a small detail people might usually miss and why it matters."},{"id":"change","name":"A Change and Its Effect","guidance":"Focus on what is different and the concrete effect of that difference."},{"id":"choice","name":"A Meaningful Choice","guidance":"Give the details that help a reader understand a preference or decision."},{"id":"cause","name":"A Reason Behind Something","guidance":"Connect a fact or feeling to its specific cause, using level-appropriate language."}],"structures":[{"id":"detail_first","guidance":"Start from one concrete detail and develop its significance."},{"id":"purpose_first","guidance":"Make the author's purpose clear, then supply only the details that serve it."},{"id":"contrast","guidance":"Organize around a meaningful contrast; vary where it appears in the passage."},{"id":"cause_effect","guidance":"Connect an observation or feeling with its reason or consequence."},{"id":"zoom","guidance":"Move between a broad observation and a specific example, in either direction."},{"id":"discovery","guidance":"Let a detail change the reader's understanding as the text develops."}],"levels":{"Pre-A1":{"wordCount":"100–120 words","sentenceCount":"about 8–14 short sentences, as the content needs","lineRange":"about 8–14 lines; vary with the content","sentenceLength":"mostly 6–12 words; very simple, clear, high-frequency beginner vocabulary; brief expressions may be shorter","readingType":"an accessible beginner reading text","guidance":"Keep it accessible and clear for an absolute beginner before A1 while meeting the 100-word minimum."},"A1":{"wordCount":"120–150 words","sentenceCount":"about 10–16 simple sentences, as the content needs","lineRange":"about 10–16 lines; vary with the content","sentenceLength":"7–14 words; simple, everyday vocabulary","readingType":"a short, accessible reading passage","guidance":"Use simple sentences with familiar everyday words."},"A2":{"wordCount":"150–190 words","sentenceCount":"about 12–18 connected sentences, as the content needs","lineRange":"about 12–18 lines; vary with the content","sentenceLength":"8–16 words; connected, clear language","readingType":"an engaging reading passage","guidance":"Use clear connected sentences with routine vocabulary."},"B1":{"wordCount":"190–230 words","sentenceCount":"about 14–20 sentences, as the content needs","lineRange":"about 14–20 lines; vary with the content","sentenceLength":"10–20 words; natural, expressive language","readingType":"an engaging reading passage","guidance":"Rich, natural language appropriate for intermediate learners."},"B2":{"wordCount":"230–270 words","sentenceCount":"about 16–22 sentences, as the content needs","lineRange":"about 16–22 lines; vary with the content","sentenceLength":"11–22 words; natural, expressive language","readingType":"an engaging, nuanced reading passage","guidance":"Rich, nuanced language appropriate for upper-intermediate learners."},"C1":{"wordCount":"270–300 words","sentenceCount":"about 18–25 sentences, as the content needs","lineRange":"about 18–25 lines; vary with the content","sentenceLength":"12–24 words; natural, expressive, advanced language","readingType":"an advanced, comprehensive reading passage","guidance":"Sophisticated, natural language appropriate for advanced learners."},"C2":{"wordCount":"280–300 words","sentenceCount":"about 18–26 sentences, as the content needs","lineRange":"about 18–26 lines; vary with the content","sentenceLength":"12–25 words; fluent, expressive, mastery-level language","readingType":"a mastery-level reading passage","guidance":"Fluent, sophisticated language appropriate for mastery-level learners."}},"preambles":["^(?:this\\s+(?:is|presents|shows)\\s+a(?:n)?|here\\s+is\\s+a(?:n)?|in\\s+this)\\s+(?:short\\s+)?(?:text\\s+message(?:\\s+chat)?|chat(?:\\s+conversation)?|conversation|dialogue|dialog|story|reading\\s+passage|passage|description|exchange|scene)\\b[^.!?\\n]*[.!?]?\\s*","^(?:este\\s+es\\s+un(?:a)?|esta\\s+es\\s+un(?:a)?|aquí\\s+hay\\s+un(?:a)?|en\\s+este\\s+mensaje|en\\s+esta\\s+conversación|en\\s+esta\\s+lectura)\\s+(?:corto\\s+|corta\\s+)?(?:mensaje\\s+de\\s+texto|chat|conversación|diálogo|historia|descripción|lectura|escena)\\b[^.!?\\n]*[.!?]?\\s*","^(?:ceci\\s+est\\s+un(?:e)?|voici\\s+un(?:e)?|dans\\s+ce(?:tte)?)\\s+(?:court(?:e)?\\s+)?(?:message\\s+texte|chat|conversation|dialogue|histoire|description|lecture)\\b[^.!?\\n]*[.!?]?\\s*","^(?:est[ea]\\s+é\\s+um(?:a)?|aqui\\s+está\\s+um(?:a)?|nest[ea])\\s+(?:curt[oa]\\s+)?(?:mensagem(?:\\s+de\\s+texto)?|chat|conversa(?:ção)?|diálogo|história|leitura)\\b[^.!?\\n]*[.!?]?\\s*","^(?:dies\\s+ist\\s+ein(?:e)?|hier\\s+ist\\s+ein(?:e)?)\\s+(?:kurze(?:s)?\\s+)?(?:textnachricht|chat|unterhaltung|gespräch|dialog|geschichte|lesetext)\\b[^.!?\\n]*[.!?]?\\s*","^(?:quest[oa]\\s+è\\s+un[a']?|ecco\\s+un[a']?)\\s+(?:breve\\s+)?(?:messaggio(?:\\s+di\\s+testo)?|chat|conversazione|dialogo|storia|lettura)\\b[^.!?\\n]*[.!?]?\\s*"],"writer":"You write natural, engaging reading passages for language learners. Write cohesive, realistic prose (a minimum of 100 words, scaling up to 300 words based on learner proficiency level) that brings the lesson's topics, everyday situations, and vocabulary to life. Use clear, level-appropriate prose that is interesting and informative to read. Present the text as continuous single-author reading prose (no dialogue scripts or character speaker labels). Follow the requested language, level, and output protocol exactly."}"#.utf8)) }
